-- an unchanged CPU cycle count means no instruction ran in between
local npause = 0
local function cycle()
  local ok, c = pcall(PCSX.getCPUCycles)
  local s = ok and c ~= nil and tostring(c):gsub('%D', '') or ''
  return s ~= '' and s or '-'
end
