  end)
_G.gdbtrace_vsync = PCSX.Events.createEventListener('GPU::Vsync',
  function()
    frame = frame + 1
    if frame % 60 == 0 then  -- heartbeat for the stall watchdog
      local b = io.open(BEAT, 'w'); b:write(frame .. '\n'); b:close()
    end
    for _, a in ipairs(acts[frame] or {}) do
